___CSS_LOADER_EXPORT___.push([module.id, `.about-page {
  padding: 2rem 0 4rem;
  min-height: 100vh;
}
.about-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: 1rem;
  letter-spacing: 0.03em;
  color: var(--color-text-primary);
}
.about-intro {
  text-align: center;
  max-width: 650px;
  margin: 0 auto 3rem;
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.8;
}

/* Sections */
.about-section {
  margin-bottom: 3rem;
}
.about-section-title {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 0.5rem;
  letter-spacing: 0.03em;
}
.about-section-desc {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin-bottom: 1.25rem;
}

/* List */
.about-list {
  display: grid;
  gap: 1rem;
}
.about-item {
  padding: 1.25rem 1.5rem;
}
.about-item h3 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 0.375rem;
}
.about-item p {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.65;
}
.about-item-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.about-item-red {
  border-color: rgba(239, 68, 68, 0.15);
}

/* Links */
.about-links-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}
.about-link-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1.25rem;
  color: var(--color-text-secondary);
  text-decoration: none;
  font-weight: 500;
  transition: all 0.2s;
}
.about-link-card:hover {
  color: var(--color-purple-light);
  border-color: rgba(167, 139, 250, 0.3);
  transform: translateY(-2px);
}
.about-link-icon {
  font-size: 1.5rem;
}
