interface TierContextValue {
  tierId: string;
  tier: TierConfig;
}

const TierContext = createContext<TierContextValue>({
  tierId: 'free',
  tier: TIER_META.free,
});

export const useTier = () => useContext(TierContext);

export const TierProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const value = useMemo<TierContextValue>(() => {
    const id = (typeof window !== 'undefined' && window.__ICS_TIER__) || 'free';
    return { tierId: id, tier: TIER_META[id] || TIER_META.free };
  }, []);

  return <TierContext.Provider value={value}>{children}</TierContext.Provider>;
};

export default TierContext;
