import React, { createContext, useContext, useReducer, ReactNode } from 'react';
import { Evaluation, ComplianceLevel, RiskLevel } from '../types';
import { PRINCIPLES, RED_LINES, METRICS } from '../data/framework';

const createDefaultEvaluation = (): Evaluation => ({
  scenario: '',
  principles: PRINCIPLES.map((p) => ({
    principleId: p.id,
    compliance: 'partial' as ComplianceLevel,
    confidence: 0.5,
    notes: '',
  })),
  redLines: RED_LINES.map((r) => ({
    redLineId: r.id,
    risk: 'none' as RiskLevel,
    notes: '',
  })),
  metrics: METRICS.map((m) => ({
    metricId: m.id,
    value: 0.5,
    notes: '',
  })),
  timestamp: 0,
  language: 'en',
});

type Action =
  | { type: 'SET_SCENARIO'; payload: string }
  | { type: 'SET_PRINCIPLE'; payload: { principleId: string; compliance: ComplianceLevel } }
  | { type: 'SET_REDLINE'; payload: { redLineId: string; risk: RiskLevel } }
  | { type: 'SET_METRIC'; payload: { metricId: string; value: number } }
  | { type: 'FINALIZE' }
  | { type: 'RESET' };

function evaluationReducer(state: Evaluation, action: Action): Evaluation {
  switch (action.type) {
    case 'SET_SCENARIO':
      return { ...state, scenario: action.payload };
    case 'SET_PRINCIPLE':
      return {
        ...state,
        principles: state.principles.map((p) =>
          p.principleId === action.payload.principleId
            ? { ...p, compliance: action.payload.compliance }
            : p
        ),
      };
    case 'SET_REDLINE':
      return {
        ...state,
        redLines: state.redLines.map((r) =>
          r.redLineId === action.payload.redLineId
            ? { ...r, risk: action.payload.risk }
            : r
        ),
      };
    case 'SET_METRIC':
      return {
        ...state,
        metrics: state.metrics.map((m) =>
          m.metricId === action.payload.metricId
            ? { ...m, value: action.payload.value }
            : m
        ),
      };
    case 'FINALIZE':
      return { ...state, timestamp: Date.now() };
    case 'RESET':
      return createDefaultEvaluation();
    default:
      return state;
  }
}

interface EvaluationContextType {
  state: Evaluation;
  dispatch: React.Dispatch<Action>;
}

const EvaluationContext = createContext<EvaluationContextType | null>(null);

export const EvaluationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, dispatch] = useReducer(evaluationReducer, null, createDefaultEvaluation);
  return (
    <EvaluationContext.Provider value={{ state, dispatch }}>
      {children}
    </EvaluationContext.Provider>
  );
};

export const useEvaluation = (): EvaluationContextType => {
  const context = useContext(EvaluationContext);
  if (!context) {
    throw new Error('useEvaluation must be used within EvaluationProvider');
  }
  return context;
};
