___CSS_LOADER_EXPORT___.push([module.id, `.results-page {
  padding: 2rem 0 4rem;
  min-height: 100vh;
}
.results-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: 1.5rem;
  letter-spacing: 0.03em;
  color: var(--color-text-primary);
}

/* Alert */
.results-alert {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  border-radius: 12px;
  background: rgba(239, 68, 68, 0.08);
  border: 1px solid rgba(239, 68, 68, 0.2);
  color: #fca5a5;
  font-size: 0.9375rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}
.results-alert-icon {
  font-size: 1.25rem;
}

/* Overall card */
.results-overall {
  text-align: center;
  padding: 2.5rem 2rem;
  margin-bottom: 1.5rem;
}
.results-overall-score {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.25rem;
}
.results-score-num {
  font-family: var(--font-display);
  font-size: 3.5rem;
  font-weight: 900;
  letter-spacing: -0.02em;
}
.results-score-label {
  font-size: 1.25rem;
  color: var(--color-text-muted);
}
.results-grade {
  font-size: 1.125rem;
  font-weight: 700;
  margin-top: 0.5rem;
}
.results-scenario {
  margin-top: 1.5rem;
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* Radar */
.results-radar {
  text-align: center;
  padding: 2rem;
  margin-bottom: 1.5rem;
}

/* Section */
.results-section {
  margin-bottom: 2rem;
}
.results-section-title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 1rem;
  letter-spacing: 0.03em;
}
.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
}
.results-item {
  padding: 1.25rem;
}
.results-item.violated {
  border-color: rgba(239, 68, 68, 0.3);
  background: rgba(239, 68, 68, 0.03);
}
.results-item-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}
.results-badge {
  padding: 0.25rem 0.75rem;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.results-item-name {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  font-weight: 500;
}

/* Metrics table */
.results-metrics-table {
  padding: 1.5rem;
}
.results-metric-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}
.results-metric-row:last-child {
  border-bottom: none;
}
.results-metric-id {
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-purple-light);
  min-width: 48px;
  letter-spacing: 0.06em;
}
.results-metric-name {
  flex: 1;
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.results-metric-bar-wrap {
  width: 120px;
  height: 6px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
  overflow: hidden;
}
.results-metric-bar {
  height: 100%;
  border-radius: 3px;
  transition: width 0.6s ease;
}
.results-metric-val {
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--color-text-primary);
  min-width: 40px;
  text-align: right;
}

/* Actions */
.results-actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

@media print {
  .results-actions,
  .compass-nav {
    display: none !important;
  }
  .results-page {
    padding-top: 0;
  }
}

@media (max-width: 768px) {
  .results-metric-name {
    font-size: 0.75rem;
  }
  .results-metric-bar-wrap {
    width: 80px;
  }
}
