___CSS_LOADER_EXPORT___.push([module.id, `.compass-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(10, 22, 40, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(167, 139, 250, 0.1);
  z-index: 100;
}

.compass-nav-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.compass-nav-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: var(--color-text-primary);
}

.compass-nav-logo {
  width: 36px;
  height: 36px;
}

.compass-nav-title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.compass-nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.compass-nav-link {
  padding: 0.5rem 0.875rem;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: all 0.2s;
  letter-spacing: 0.02em;
}
.compass-nav-link:hover {
  color: var(--color-text-primary);
  background: rgba(167, 139, 250, 0.1);
}
.compass-nav-link.active {
  color: var(--color-purple-light);
  background: rgba(167, 139, 250, 0.15);
}

.compass-nav-lang {
  margin-left: 0.5rem;
  padding: 0.375rem 0.875rem;
  border-radius: 6px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-cyan-light);
  background: rgba(6, 182, 212, 0.1);
  border: 1px solid rgba(6, 182, 212, 0.2);
  cursor: pointer;
  transition: all 0.2s;
  letter-spacing: 0.04em;
}
.compass-nav-lang:hover {
  background: rgba(6, 182, 212, 0.2);
  border-color: rgba(6, 182, 212, 0.4);
}

/* Hamburger */
.compass-nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
  background: none;
  border: none;
  cursor: pointer;
}
.compass-nav-hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-text-secondary);
  border-radius: 1px;
  transition: all 0.3s;
}
.compass-nav-hamburger.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}
.compass-nav-hamburger.open span:nth-child(2) {
  opacity: 0;
}
.compass-nav-hamburger.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

@media (max-width: 768px) {
  .compass-nav-hamburger {
    display: flex;
  }
  .compass-nav-links {
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    flex-direction: column;
    background: rgba(10, 22, 40, 0.95);
    backdrop-filter: blur(16px);
    padding: 1rem;
    gap: 0.25rem;
    border-bottom: 1px solid rgba(167, 139, 250, 0.1);
    transform: translateY(-100%);
    opacity: 0;
    pointer-events: none;
    transition: all 0.3s;
  }
  .compass-nav-links.open {
    transform: translateY(0);
    opacity: 1;
    pointer-events: auto;
  }
  .compass-nav-link {
    width: 100%;
    padding: 0.75rem 1rem;
  }
  .compass-nav-lang {
    margin-left: 0;
    margin-top: 0.5rem;
    width: 100%;
    text-align: center;
  }
}
