import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import './Navbar.css';

const Navbar: React.FC = () => {
  const { t, i18n } = useTranslation();
  const location = useLocation();
  const [menuOpen, setMenuOpen] = React.useState(false);

  const toggleLang = () => {
    i18n.changeLanguage(i18n.language === 'en' ? 'zh' : 'en');
  };

  const navItems = [
    { path: '/', label: t('nav.home') },
    { path: '/evaluate', label: t('nav.evaluate') },
    { path: '/results', label: t('nav.results') },
    { path: '/about', label: t('nav.about') },
  ];

  return (
    <nav className="compass-nav">
      <div className="compass-nav-inner">
        <Link to="/" className="compass-nav-brand">
          <svg className="compass-nav-logo" viewBox="0 0 36 36" fill="none">
            <circle cx="18" cy="18" r="16" stroke="rgba(167,139,250,0.3)" strokeWidth="1" fill="none" />
            <circle cx="18" cy="18" r="10" stroke="rgba(6,182,212,0.2)" strokeWidth="1" fill="none" />
            <circle cx="18" cy="18" r="4" fill="#a78bfa" />
            <circle cx="18" cy="4" r="2" fill="#06b6d4">
              <animateTransform attributeName="transform" type="rotate" from="0 18 18" to="360 18 18" dur="8s" repeatCount="indefinite" />
            </circle>
          </svg>
          <div className="compass-nav-brand-text">
            <span className="compass-nav-title">
              {i18n.language === 'zh' ? '星际罗盘' : 'ICS Compass'}
            </span>
          </div>
        </Link>

        <button
          className={`compass-nav-hamburger ${menuOpen ? 'open' : ''}`}
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Toggle menu"
        >
          <span /><span /><span />
        </button>

        <div className={`compass-nav-links ${menuOpen ? 'open' : ''}`}>
          {navItems.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`compass-nav-link ${location.pathname === item.path ? 'active' : ''}`}
              onClick={() => setMenuOpen(false)}
            >
              {item.label}
            </Link>
          ))}
          <button className="compass-nav-lang" onClick={toggleLang}>
            {i18n.language === 'en' ? '中文' : 'EN'}
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
