import React from 'react';

interface RadarChartProps {
  labels: string[];
  values: number[];       // 0–1 normalized
  maxValues?: number[];   // for display scaling
  size?: number;
  color?: string;
}

const RadarChart: React.FC<RadarChartProps> = ({
  labels,
  values,
  size = 300,
  color = '#a78bfa',
}) => {
  const cx = size / 2;
  const cy = size / 2;
  const radius = size * 0.38;
  const n = labels.length;
  const angleStep = (Math.PI * 2) / n;
  const levels = 5;

  // Get point on circle
  const getPoint = (index: number, r: number) => {
    const angle = angleStep * index - Math.PI / 2;
    return {
      x: cx + r * Math.cos(angle),
      y: cy + r * Math.sin(angle),
    };
  };

  // Grid lines
  const gridPaths: string[] = [];
  for (let lv = 1; lv <= levels; lv++) {
    const r = (radius / levels) * lv;
    const points = Array.from({ length: n }, (_, i) => {
      const p = getPoint(i, r);
      return `${p.x},${p.y}`;
    });
    gridPaths.push(`M${points.join('L')}Z`);
  }

  // Data polygon
  const dataPoints = values.map((v, i) => {
    const clampedV = Math.min(1, Math.max(0, v));
    const p = getPoint(i, radius * clampedV);
    return `${p.x},${p.y}`;
  });
  const dataPath = `M${dataPoints.join('L')}Z`;

  // Data dots
  const dots = values.map((v, i) => {
    const clampedV = Math.min(1, Math.max(0, v));
    return getPoint(i, radius * clampedV);
  });

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ display: 'block', margin: '0 auto' }}>
      {/* Grid */}
      {gridPaths.map((d, i) => (
        <path key={i} d={d} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="1" />
      ))}

      {/* Axis lines */}
      {Array.from({ length: n }, (_, i) => {
        const p = getPoint(i, radius);
        return (
          <line key={i} x1={cx} y1={cy} x2={p.x} y2={p.y} stroke="rgba(255,255,255,0.06)" strokeWidth="1" />
        );
      })}

      {/* Data area */}
      <path d={dataPath} fill={color} fillOpacity="0.15" stroke={color} strokeWidth="2" />

      {/* Data dots */}
      {dots.map((p, i) => (
        <circle key={i} cx={p.x} cy={p.y} r="4" fill={color} stroke="white" strokeWidth="1.5" />
      ))}

      {/* Labels */}
      {labels.map((label, i) => {
        const p = getPoint(i, radius + 24);
        const angle = angleStep * i - Math.PI / 2;
        let anchor: 'middle' | 'start' | 'end' = 'middle';
        if (Math.cos(angle) > 0.3) anchor = 'start';
        else if (Math.cos(angle) < -0.3) anchor = 'end';

        return (
          <text
            key={i}
            x={p.x}
            y={p.y}
            textAnchor={anchor}
            dominantBaseline="central"
            fill="rgba(255,255,255,0.7)"
            fontSize="11"
            fontFamily="var(--font-display)"
            fontWeight="600"
            letterSpacing="0.06em"
          >
            {label}
          </text>
        );
      })}

      {/* Value labels */}
      {values.map((v, i) => {
        const p = getPoint(i, radius * Math.min(1, Math.max(0, v)) + 14);
        return (
          <text
            key={`v${i}`}
            x={p.x}
            y={p.y}
            textAnchor="middle"
            dominantBaseline="central"
            fill={color}
            fontSize="10"
            fontWeight="700"
            fontFamily="var(--font-display)"
          >
            {v.toFixed(2)}
          </text>
        );
      })}
    </svg>
  );
};

export default RadarChart;
