import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useEvaluation } from '../context/EvaluationContext';
import { principles, redLines, metrics } from '../data/framework';
import type { ComplianceLevel, RiskLevel } from '../types';
import './Evaluate.css';

const STEPS = 4;

const complianceLevels: ComplianceLevel[] = ['compliant', 'partial', 'non-compliant'];
const riskLevels: RiskLevel[] = ['none', 'low', 'medium', 'high', 'violated'];

const complianceColors: Record<ComplianceLevel, string> = {
  compliant: '#10b981',
  partial: '#f59e0b',
  'non-compliant': '#ef4444',
};

const riskColors: Record<RiskLevel, string> = {
  none: '#10b981',
  low: '#22d3ee',
  medium: '#f59e0b',
  high: '#f97316',
  violated: '#ef4444',
};

const Evaluate: React.FC = () => {
  const { t, i18n } = useTranslation();
  const lang = i18n.language as 'en' | 'zh';
  const { state, dispatch } = useEvaluation();
  const navigate = useNavigate();
  const [step, setStep] = useState(0);

  const stepLabels = [
    t('evaluate.step1'),
    t('evaluate.step2'),
    t('evaluate.step3'),
    t('evaluate.step4'),
  ];

  const next = () => {
    if (step < STEPS - 1) setStep(step + 1);
    else {
      dispatch({ type: 'FINALIZE' });
      navigate('/results');
    }
  };
  const prev = () => { if (step > 0) setStep(step - 1); };

  return (
    <div className="evaluate-page">
      <div className="container">
        {/* Progress */}
        <div className="eval-progress">
          {stepLabels.map((label, i) => (
            <div key={i} className={`eval-progress-step ${i === step ? 'active' : ''} ${i < step ? 'done' : ''}`}>
              <div className="eval-progress-dot">{i < step ? '✓' : i + 1}</div>
              <span className="eval-progress-label">{label}</span>
            </div>
          ))}
          <div className="eval-progress-bar">
            <div className="eval-progress-fill" style={{ width: `${(step / (STEPS - 1)) * 100}%` }} />
          </div>
        </div>

        {/* Step 0 — Scenario */}
        {step === 0 && (
          <div className="eval-section fade-in">
            <h2 className="eval-heading">{t('evaluate.scenarioTitle')}</h2>
            <p className="eval-desc">{t('evaluate.scenarioDesc')}</p>
            <textarea
              className="eval-textarea"
              rows={5}
              placeholder={t('evaluate.scenarioPlaceholder')}
              value={state.scenario}
              onChange={(e) => dispatch({ type: 'SET_SCENARIO', payload: e.target.value })}
            />
          </div>
        )}

        {/* Step 1 — Principles */}
        {step === 1 && (
          <div className="eval-section fade-in">
            <h2 className="eval-heading">{t('evaluate.principlesTitle')}</h2>
            <div className="eval-cards">
              {principles.map((p) => {
                const pa = state.principles.find((a) => a.principleId === p.id);
                return (
                  <div key={p.id} className="card eval-item-card">
                    <div className="eval-item-header">
                      <span className="eval-item-id">{p.id}</span>
                      <span className="eval-item-priority">P{p.priority}</span>
                    </div>
                    <h3 className="eval-item-name">{p.name[lang]}</h3>
                    <p className="eval-item-desc">{p.description[lang]}</p>
                    <div className="eval-compliance-row">
                      {complianceLevels.map((lv) => (
                        <button
                          key={lv}
                          className={`eval-chip ${pa?.compliance === lv ? 'selected' : ''}`}
                          style={pa?.compliance === lv ? { background: complianceColors[lv], color: '#fff', borderColor: complianceColors[lv] } : {}}
                          onClick={() => dispatch({ type: 'SET_PRINCIPLE', payload: { principleId: p.id, compliance: lv } })}
                        >
                          {t(`evaluate.${lv}`)}
                        </button>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Step 2 — Red Lines */}
        {step === 2 && (
          <div className="eval-section fade-in">
            <h2 className="eval-heading">{t('evaluate.redLinesTitle')}</h2>
            <div className="eval-cards">
              {redLines.map((rl) => {
                const ra = state.redLines.find((a) => a.redLineId === rl.id);
                return (
                  <div key={rl.id} className="card eval-item-card">
                    <div className="eval-item-header">
                      <span className="eval-item-id">{rl.id}</span>
                    </div>
                    <h3 className="eval-item-name">{rl.name[lang]}</h3>
                    <p className="eval-item-desc">{rl.description[lang]}</p>
                    <div className="eval-risk-row">
                      {riskLevels.map((lv) => (
                        <button
                          key={lv}
                          className={`eval-chip ${ra?.risk === lv ? 'selected' : ''}`}
                          style={ra?.risk === lv ? { background: riskColors[lv], color: '#fff', borderColor: riskColors[lv] } : {}}
                          onClick={() => dispatch({ type: 'SET_REDLINE', payload: { redLineId: rl.id, risk: lv } })}
                        >
                          {t(`evaluate.risk_${lv}`)}
                        </button>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Step 3 — Metrics */}
        {step === 3 && (
          <div className="eval-section fade-in">
            <h2 className="eval-heading">{t('evaluate.metricsTitle')}</h2>
            <div className="eval-cards">
              {metrics.map((m) => {
                const ms = state.metrics.find((s) => s.metricId === m.id);
                const val = ms?.value ?? 0.5;
                return (
                  <div key={m.id} className="card eval-item-card">
                    <div className="eval-item-header">
                      <span className="eval-item-id">{m.id}</span>
                      <span className="eval-item-range">{m.range}</span>
                    </div>
                    <h3 className="eval-item-name">{m.name[lang]}</h3>
                    <p className="eval-item-desc">{m.description[lang]}</p>
                    <div className="eval-slider-row">
                      <input
                        type="range"
                        className="eval-slider"
                        min="0"
                        max="1"
                        step="0.01"
                        value={val}
                        onChange={(e) => dispatch({ type: 'SET_METRIC', payload: { metricId: m.id, value: parseFloat(e.target.value) } })}
                      />
                      <span className="eval-slider-value">{val.toFixed(2)}</span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Navigation */}
        <div className="eval-nav-buttons">
          <button className="btn btn-secondary" onClick={prev} disabled={step === 0}>
            {t('common.previous')}
          </button>
          <button className="btn btn-primary" onClick={next}>
            {step < STEPS - 1 ? t('common.next') : t('common.finish')}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Evaluate;
