___CSS_LOADER_EXPORT___.push([module.id, `.home-page {
  min-height: 100vh;
}

/* Hero */
.home-hero {
  position: relative;
  padding: 6rem 1.5rem 4rem;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 70vh;
}
.home-hero-inner {
  text-align: center;
  max-width: 700px;
  position: relative;
  z-index: 2;
}
.home-badge {
  display: inline-block;
  padding: 0.375rem 1rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-purple-light);
  background: rgba(167, 139, 250, 0.1);
  border: 1px solid rgba(167, 139, 250, 0.2);
  margin-bottom: 1.5rem;
}
.home-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: 0.04em;
  line-height: 1.15;
  color: var(--color-text-primary);
  margin-bottom: 1.25rem;
  background: linear-gradient(135deg, #ffffff 0%, #a78bfa 50%, #06b6d4 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.home-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: 2.5rem;
}
.home-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* Orbits decoration */
.home-hero-orbits {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.orbit {
  position: absolute;
  top: 50%;
  left: 50%;
  border-radius: 50%;
  border: 1px solid rgba(167, 139, 250, 0.06);
}
.orbit-1 {
  width: 400px;
  height: 400px;
  margin: -200px 0 0 -200px;
  animation: orbit-spin 30s linear infinite;
}
.orbit-2 {
  width: 600px;
  height: 600px;
  margin: -300px 0 0 -300px;
  border-color: rgba(6, 182, 212, 0.04);
  animation: orbit-spin 50s linear infinite reverse;
}
.orbit-3 {
  width: 800px;
  height: 800px;
  margin: -400px 0 0 -400px;
  border-color: rgba(245, 158, 11, 0.03);
  animation: orbit-spin 70s linear infinite;
}
@keyframes orbit-spin {
  to { transform: rotate(360deg); }
}

/* Features */
.home-features {
  padding: 4rem 0;
}
.home-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
}
.feature-card {
  text-align: center;
  padding: 2rem 1.5rem;
}
.feature-icon {
  font-size: 2.5rem;
  display: block;
  margin-bottom: 1rem;
}
.feature-title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 0.5rem;
  letter-spacing: 0.03em;
}
.feature-desc {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

/* Quote */
.home-quote {
  padding: 3rem 0 5rem;
}
.home-blockquote {
  text-align: center;
  max-width: 600px;
  margin: 0 auto;
  padding: 2rem;
  border-left: 3px solid var(--color-purple);
  background: rgba(167, 139, 250, 0.03);
  border-radius: 0 12px 12px 0;
}
.home-blockquote p {
  font-size: 1.125rem;
  font-style: italic;
  color: var(--color-text-secondary);
  line-height: 1.8;
  margin-bottom: 0.75rem;
}
.home-blockquote cite {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  font-style: normal;
}
