import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useEvaluation } from '../context/EvaluationContext';
import { principles, redLines, metrics } from '../data/framework';
import RadarChart from '../components/RadarChart';
import type { ComplianceLevel, RiskLevel } from '../types';
import './Results.css';

const complianceBadge: Record<ComplianceLevel, { color: string; bg: string }> = {
  compliant: { color: '#10b981', bg: 'rgba(16,185,129,0.1)' },
  partial: { color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
  'non-compliant': { color: '#ef4444', bg: 'rgba(239,68,68,0.1)' },
};

const riskBadge: Record<RiskLevel, { color: string; bg: string }> = {
  none: { color: '#10b981', bg: 'rgba(16,185,129,0.1)' },
  low: { color: '#22d3ee', bg: 'rgba(34,211,238,0.1)' },
  medium: { color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
  high: { color: '#f97316', bg: 'rgba(249,115,22,0.1)' },
  violated: { color: '#ef4444', bg: 'rgba(239,68,68,0.1)' },
};

const Results: React.FC = () => {
  const { t, i18n } = useTranslation();
  const lang = i18n.language as 'en' | 'zh';
  const { state } = useEvaluation();

  const hasViolation = state.redLines.some((r) => r.risk === 'violated');
  const hasHighRisk = state.redLines.some((r) => r.risk === 'high' || r.risk === 'violated');

  // Radar chart data
  const radarLabels = metrics.map((m) => m.id);
  const radarValues = metrics.map((m) => {
    const ms = state.metrics.find((s) => s.metricId === m.id);
    return ms?.value ?? 0.5;
  });

  // Overall score — simple average
  const overallScore = radarValues.reduce((a, b) => a + b, 0) / radarValues.length;

  // Grade
  const getGrade = (score: number): { label: string; color: string } => {
    if (hasViolation) return { label: lang === 'zh' ? '⛔ 红线违反' : '⛔ Red Line Violated', color: '#ef4444' };
    if (score >= 0.8) return { label: lang === 'zh' ? '✅ 优秀' : '✅ Excellent', color: '#10b981' };
    if (score >= 0.6) return { label: lang === 'zh' ? '🟡 良好' : '🟡 Good', color: '#f59e0b' };
    if (score >= 0.4) return { label: lang === 'zh' ? '🟠 需改进' : '🟠 Needs Improvement', color: '#f97316' };
    return { label: lang === 'zh' ? '🔴 严重关切' : '🔴 Serious Concern', color: '#ef4444' };
  };

  const grade = getGrade(overallScore);

  return (
    <div className="results-page">
      <div className="container">
        <h1 className="results-title">{t('results.title')}</h1>

        {/* Alert */}
        {hasHighRisk && (
          <div className="results-alert">
            <span className="results-alert-icon">⚠️</span>
            <span>{t(hasViolation ? 'results.violationAlert' : 'results.highRiskAlert')}</span>
          </div>
        )}

        {/* Overall */}
        <div className="results-overall card">
          <div className="results-overall-score">
            <span className="results-score-num" style={{ color: grade.color }}>
              {(overallScore * 100).toFixed(0)}
            </span>
            <span className="results-score-label">/100</span>
          </div>
          <div className="results-grade" style={{ color: grade.color }}>{grade.label}</div>
          {state.scenario && (
            <p className="results-scenario">
              <strong>{lang === 'zh' ? '评估场景：' : 'Scenario: '}</strong>
              {state.scenario}
            </p>
          )}
        </div>

        {/* Radar chart */}
        <div className="results-radar card">
          <h2 className="results-section-title">{t('results.radarTitle')}</h2>
          <RadarChart labels={radarLabels} values={radarValues} size={340} />
        </div>

        {/* Principles */}
        <div className="results-section">
          <h2 className="results-section-title">{t('results.principlesTitle')}</h2>
          <div className="results-grid">
            {principles.map((p) => {
              const pa = state.principles.find((a) => a.principleId === p.id);
              const compliance = pa?.compliance || 'partial';
              const badge = complianceBadge[compliance];
              return (
                <div key={p.id} className="card results-item">
                  <div className="results-item-top">
                    <span className="eval-item-id">{p.id}</span>
                    <span className="results-badge" style={{ color: badge.color, background: badge.bg }}>
                      {t(`evaluate.${compliance}`)}
                    </span>
                  </div>
                  <h3 className="results-item-name">{p.name[lang]}</h3>
                </div>
              );
            })}
          </div>
        </div>

        {/* Red Lines */}
        <div className="results-section">
          <h2 className="results-section-title">{t('results.redLinesTitle')}</h2>
          <div className="results-grid">
            {redLines.map((rl) => {
              const ra = state.redLines.find((a) => a.redLineId === rl.id);
              const risk = ra?.risk || 'none';
              const badge = riskBadge[risk];
              return (
                <div key={rl.id} className={`card results-item ${risk === 'violated' ? 'violated' : ''}`}>
                  <div className="results-item-top">
                    <span className="eval-item-id">{rl.id}</span>
                    <span className="results-badge" style={{ color: badge.color, background: badge.bg }}>
                      {t(`evaluate.risk_${risk}`)}
                    </span>
                  </div>
                  <h3 className="results-item-name">{rl.name[lang]}</h3>
                </div>
              );
            })}
          </div>
        </div>

        {/* Metrics table */}
        <div className="results-section">
          <h2 className="results-section-title">{t('results.metricsTitle')}</h2>
          <div className="results-metrics-table card">
            {metrics.map((m) => {
              const ms = state.metrics.find((s) => s.metricId === m.id);
              const val = ms?.value ?? 0.5;
              return (
                <div key={m.id} className="results-metric-row">
                  <span className="results-metric-id">{m.id}</span>
                  <span className="results-metric-name">{m.name[lang]}</span>
                  <div className="results-metric-bar-wrap">
                    <div
                      className="results-metric-bar"
                      style={{ width: `${val * 100}%`, background: val >= 0.6 ? '#10b981' : val >= 0.3 ? '#f59e0b' : '#ef4444' }}
                    />
                  </div>
                  <span className="results-metric-val">{val.toFixed(2)}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Actions */}
        <div className="results-actions">
          <Link to="/evaluate" className="btn btn-primary">{t('results.reEvaluate')}</Link>
          <button className="btn btn-secondary" onClick={() => window.print()}>
            {t('results.export')}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Results;
