   Brand: Deep-space theme
   ============================================ */

:root {
  /* === Colors === */
  --color-bg-deep: #0a1628;
  --color-bg-card: rgba(255, 255, 255, 0.03);
  --color-bg-card-hover: rgba(255, 255, 255, 0.06);
  --color-border: rgba(167, 139, 250, 0.15);
  --color-border-hover: rgba(167, 139, 250, 0.3);

  --color-purple: #a78bfa;
  --color-purple-dark: #7c3aed;
  --color-purple-light: #c4b5fd;
  --color-cyan: #06b6d4;
  --color-cyan-light: #22d3ee;
  --color-gold: #f59e0b;
  --color-gold-light: #fbbf24;
  --color-red: #ef4444;
  --color-green: #10b981;

  --color-text-primary: rgba(255, 255, 255, 0.95);
  --color-text-secondary: rgba(255, 255, 255, 0.7);
  --color-text-muted: rgba(255, 255, 255, 0.45);

  /* === Fonts === */
  --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: 'Orbitron', 'Noto Serif SC', monospace;
  --font-zh-body: 'Noto Sans SC', sans-serif;
  --font-zh-title: 'Noto Serif SC', serif;

  /* === Spacing === */
  --container-max: 960px;
  --nav-height: 64px;

  /* === Transitions === */
  --ease-out: cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* === Reset === */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg-deep);
  color: var(--color-text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: var(--color-purple-light);
  text-decoration: none;
  transition: color 0.2s var(--ease-out);
}
a:hover {
  color: var(--color-cyan-light);
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

img, svg {
  display: block;
  max-width: 100%;
}

/* === Utility Classes === */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* === Card === */
.card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: 16px;
  padding: 1.5rem;
  transition: all 0.3s var(--ease-out);
}
.card:hover {
  background: var(--color-bg-card-hover);
  border-color: var(--color-border-hover);
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: 12px;
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: all 0.25s var(--ease-out);
  text-transform: uppercase;
}

.btn-primary {
  background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
  color: white;
  box-shadow: 0 4px 20px rgba(167, 139, 250, 0.3);
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(167, 139, 250, 0.45);
  color: white;
}

.btn-secondary {
  background: rgba(167, 139, 250, 0.1);
  color: var(--color-purple-light);
  border: 1px solid var(--color-border);
}
.btn-secondary:hover {
  background: rgba(167, 139, 250, 0.2);
  border-color: var(--color-border-hover);
  color: var(--color-purple-light);
}

.btn-cyan {
  background: linear-gradient(135deg, var(--color-cyan), #0891b2);
  color: white;
  box-shadow: 0 4px 20px rgba(6, 182, 212, 0.3);
}
.btn-cyan:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(6, 182, 212, 0.45);
  color: white;
}

/* === Section Titles === */
.section-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.section-subtitle {
  font-size: 1.0625rem;
  color: var(--color-text-secondary);
  line-height: 1.8;
  max-width: 640px;
}

/* === Form Elements === */
.input-field {
  width: 100%;
  padding: 0.875rem 1rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  line-height: 1.6;
  transition: border-color 0.2s;
  resize: vertical;
}
.input-field:focus {
  outline: none;
  border-color: var(--color-purple);
  box-shadow: 0 0 0 3px rgba(167, 139, 250, 0.15);
}
.input-field::placeholder {
  color: var(--color-text-muted);
}

/* === Slider === */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--color-purple);
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(167, 139, 250, 0.4);
  transition: transform 0.15s;
}
input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

/* === Badges === */
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.badge-purple {
  background: rgba(167, 139, 250, 0.15);
  color: var(--color-purple-light);
}
.badge-cyan {
  background: rgba(6, 182, 212, 0.15);
  color: var(--color-cyan-light);
}
.badge-gold {
  background: rgba(245, 158, 11, 0.15);
  color: var(--color-gold-light);
}
.badge-red {
  background: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
}
.badge-green {
  background: rgba(16, 185, 129, 0.15);
  color: #6ee7b7;
}

/* === Responsive === */
@media (max-width: 768px) {
  :root {
    --container-max: 100%;
  }
  .section-title {
    font-size: 1.375rem;
  }
  .btn {
    padding: 0.625rem 1.25rem;
    font-size: 0.875rem;
  }
}

/* === Animations === */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 20px rgba(167, 139, 250, 0.2); }
  50% { box-shadow: 0 0 40px rgba(167, 139, 250, 0.4); }
}

.animate-in {
  animation: fadeInUp 0.6s var(--ease-out) both;
}
