import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import './Home.css';

const Home: React.FC = () => {
  const { t, i18n } = useTranslation();
  const lang = i18n.language as 'en' | 'zh';

  const features = [
    {
      icon: '⚖️',
      title: lang === 'zh' ? '三原则评估' : '3 Principles',
      desc: lang === 'zh'
        ? '递归自由原则 · 负熵责任原则 · 可逆性原则'
        : 'Recursive Freedom · Negentropy Responsibility · Reversibility',
    },
    {
      icon: '🚫',
      title: lang === 'zh' ? '五条禁止红线' : '5 Red Lines',
      desc: lang === 'zh'
        ? '不可触碰的底线守护文明安全'
        : 'Inviolable boundaries safeguarding civilization',
    },
    {
      icon: '📊',
      title: lang === 'zh' ? '六维度量化' : '6 Metrics',
      desc: lang === 'zh'
        ? 'UCS · RFD · CDI · CRV · MBCL · CSIA 雷达图谱'
        : 'UCS · RFD · CDI · CRV · MBCL · CSIA Radar Profile',
    },
    {
      icon: '🌐',
      title: lang === 'zh' ? '双语报告' : 'Bilingual Reports',
      desc: lang === 'zh'
        ? '即时生成中英双语评估报告'
        : 'Generate assessment reports in EN / ZH instantly',
    },
  ];

  return (
    <div className="home-page">
      <section className="home-hero">
        <div className="home-hero-inner">
          <span className="home-badge">{t('home.badge')}</span>
          <h1 className="home-title">{t('home.title')}</h1>
          <p className="home-subtitle">{t('home.subtitle')}</p>
          <div className="home-actions">
            <Link to="/evaluate" className="btn btn-primary btn-lg">
              {t('home.cta')}
            </Link>
            <Link to="/about" className="btn btn-secondary btn-lg">
              {t('home.learnMore')}
            </Link>
          </div>
        </div>

        {/* Decorative orbit rings */}
        <div className="home-hero-orbits">
          <div className="orbit orbit-1" />
          <div className="orbit orbit-2" />
          <div className="orbit orbit-3" />
        </div>
      </section>

      <section className="home-features">
        <div className="container">
          <div className="home-features-grid">
            {features.map((f, i) => (
              <div key={i} className="feature-card card">
                <span className="feature-icon">{f.icon}</span>
                <h3 className="feature-title">{f.title}</h3>
                <p className="feature-desc">{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="home-quote">
        <div className="container">
          <blockquote className="home-blockquote">
            <p>
              {lang === 'zh'
                ? '"文明的高度不在于它能创造什么，而在于它选择不做什么。"'
                : '"The measure of a civilization is not what it can create, but what it chooses not to."'}
            </p>
            <cite>— ICS Framework Preamble</cite>
          </blockquote>
        </div>
      </section>
    </div>
  );
};

export default Home;
