  padding: 2rem 0 4rem;
  min-height: 100vh;
}

/* Progress bar */
.eval-progress {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2rem;
  position: relative;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}
.eval-progress-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  z-index: 1;
}
.eval-progress-dot {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8125rem;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.05);
  border: 2px solid rgba(255, 255, 255, 0.1);
  color: var(--color-text-muted);
  transition: all 0.3s;
}
.eval-progress-step.active .eval-progress-dot {
  background: var(--color-purple);
  border-color: var(--color-purple);
  color: #fff;
  box-shadow: 0 0 20px rgba(167, 139, 250, 0.4);
}
.eval-progress-step.done .eval-progress-dot {
  background: #10b981;
  border-color: #10b981;
  color: #fff;
}
.eval-progress-label {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  font-weight: 500;
  text-align: center;
  max-width: 80px;
}
.eval-progress-step.active .eval-progress-label {
  color: var(--color-purple-light);
}
.eval-progress-bar {
  position: absolute;
  top: 18px;
  left: 10%;
  right: 10%;
  height: 2px;
  background: rgba(255, 255, 255, 0.06);
  z-index: 0;
}
.eval-progress-fill {
  height: 100%;
  background: var(--color-purple);
  transition: width 0.4s ease;
  border-radius: 2px;
}

/* Section */
.eval-section {
  max-width: 900px;
  margin: 0 auto;
}
.eval-heading {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 0.5rem;
  letter-spacing: 0.03em;
}
.eval-desc {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
  margin-bottom: 1.5rem;
  line-height: 1.6;
}

/* Textarea */
.eval-textarea {
  width: 100%;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  color: var(--color-text-primary);
  font-size: 0.9375rem;
  font-family: var(--font-body);
  line-height: 1.7;
  resize: vertical;
  transition: border-color 0.2s;
}
.eval-textarea:focus {
  outline: none;
  border-color: var(--color-purple);
  box-shadow: 0 0 0 3px rgba(167, 139, 250, 0.1);
}
.eval-textarea::placeholder {
  color: rgba(255, 255, 255, 0.25);
}

/* Cards */
.eval-cards {
  display: grid;
  gap: 1.25rem;
}
.eval-item-card {
  padding: 1.5rem;
}
.eval-item-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.eval-item-id {
  padding: 0.25rem 0.625rem;
  background: rgba(167, 139, 250, 0.1);
  color: var(--color-purple-light);
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  border-radius: 6px;
}
.eval-item-priority {
  padding: 0.2rem 0.5rem;
  background: rgba(245, 158, 11, 0.1);
  color: var(--color-gold);
  font-family: var(--font-display);
  font-size: 0.6875rem;
  font-weight: 700;
  border-radius: 4px;
  letter-spacing: 0.04em;
}
.eval-item-range {
  padding: 0.2rem 0.5rem;
  background: rgba(6, 182, 212, 0.1);
  color: var(--color-cyan-light);
  font-size: 0.6875rem;
  font-weight: 600;
  border-radius: 4px;
}
.eval-item-name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 0.375rem;
}
.eval-item-desc {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 1rem;
}

/* Compliance / Risk chips */
.eval-compliance-row,
.eval-risk-row {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.eval-chip {
  padding: 0.375rem 0.875rem;
  border-radius: 8px;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--color-text-secondary);
  transition: all 0.2s;
}
.eval-chip:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.2);
}
.eval-chip.selected {
  border-width: 2px;
}

/* Slider */
.eval-slider-row {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.eval-slider {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.08);
  outline: none;
}
.eval-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--color-purple);
  cursor: pointer;
  border: 3px solid var(--color-bg);
  box-shadow: 0 0 10px rgba(167, 139, 250, 0.5);
}
.eval-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--color-purple);
  cursor: pointer;
  border: 3px solid var(--color-bg);
}
.eval-slider-value {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-purple-light);
  min-width: 48px;
  text-align: center;
}

/* Navigation */
.eval-nav-buttons {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2.5rem;
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}
.eval-nav-buttons .btn {
  min-width: 140px;
}

/* Animation */
.fade-in {
  animation: fadeInUp 0.4s ease-out;
}

@media (max-width: 768px) {
  .eval-progress {
    gap: 1rem;
  }
  .eval-progress-label {
    font-size: 0.625rem;
  }
  .eval-risk-row {
    gap: 0.375rem;
  }
  .eval-chip {
    padding: 0.3rem 0.625rem;
    font-size: 0.75rem;
  }
}
