import React from 'react';
import { useTranslation } from 'react-i18next';
import { principles, redLines, metrics } from '../data/framework';
import './About.css';

const About: React.FC = () => {
  const { t, i18n } = useTranslation();
  const lang = i18n.language as 'en' | 'zh';

  return (
    <div className="about-page">
      <div className="container">
        <h1 className="about-title">{t('about.title')}</h1>
        <p className="about-intro">{t('about.intro')}</p>

        {/* Principles */}
        <section className="about-section">
          <h2 className="about-section-title">{t('about.principlesTitle')}</h2>
          <p className="about-section-desc">{t('about.principlesDesc')}</p>
          <div className="about-list">
            {principles.map((p) => (
              <div key={p.id} className="card about-item">
                <div className="about-item-header">
                  <span className="eval-item-id">{p.id}</span>
                  <span className="eval-item-priority">P{p.priority}</span>
                </div>
                <h3>{p.name[lang]}</h3>
                <p>{p.description[lang]}</p>
              </div>
            ))}
          </div>
        </section>

        {/* Red Lines */}
        <section className="about-section">
          <h2 className="about-section-title">{t('about.redLinesTitle')}</h2>
          <p className="about-section-desc">{t('about.redLinesDesc')}</p>
          <div className="about-list">
            {redLines.map((rl) => (
              <div key={rl.id} className="card about-item about-item-red">
                <div className="about-item-header">
                  <span className="eval-item-id" style={{ background: 'rgba(239,68,68,0.1)', color: '#fca5a5' }}>{rl.id}</span>
                </div>
                <h3>{rl.name[lang]}</h3>
                <p>{rl.description[lang]}</p>
              </div>
            ))}
          </div>
        </section>

        {/* Metrics */}
        <section className="about-section">
          <h2 className="about-section-title">{t('about.metricsTitle')}</h2>
          <p className="about-section-desc">{t('about.metricsDesc')}</p>
          <div className="about-list">
            {metrics.map((m) => (
              <div key={m.id} className="card about-item">
                <div className="about-item-header">
                  <span className="eval-item-id">{m.id}</span>
                  <span className="eval-item-range">{m.range}</span>
                </div>
                <h3>{m.name[lang]}</h3>
                <p>{m.description[lang]}</p>
              </div>
            ))}
          </div>
        </section>

        {/* Links */}
        <section className="about-section about-links">
          <h2 className="about-section-title">{t('about.linksTitle')}</h2>
          <div className="about-links-grid">
            <a href="https://ics-studies.org" target="_blank" rel="noopener noreferrer" className="card about-link-card">
              <span className="about-link-icon">🌐</span>
              <span>ics-studies.org</span>
            </a>
            <a href="https://ics-studies.org/en/daily-commentary.html" target="_blank" rel="noopener noreferrer" className="card about-link-card">
              <span className="about-link-icon">📰</span>
              <span>{lang === 'zh' ? '每日评论' : 'Daily Commentary'}</span>
            </a>
            <a href="https://ics-studies.org/en/in-depth-research.html" target="_blank" rel="noopener noreferrer" className="card about-link-card">
              <span className="about-link-icon">🔬</span>
              <span>{lang === 'zh' ? '深度研究' : 'In-depth Research'}</span>
            </a>
          </div>
        </section>
      </div>
    </div>
  );
};

export default About;
