// ============================================================
// §11  计算工具函数 (Calculation Utilities)
// ============================================================

/** Weighted geometric mean (for UCS, CDI) */
export function weightedGeometricMean(values: number[], weights: number[]): number {
  if (values.length !== weights.length) throw new Error('Values and weights must match');
  let result = 1;
  for (let i = 0; i < values.length; i++) {
    // Clamp to avoid log(0)
    const v = Math.max(values[i], 1e-10);
    result *= Math.pow(v, weights[i]);
  }
  return result;
}

/** Weighted arithmetic mean (for CRV, CSIA) */
export function weightedArithmeticMean(values: number[], weights: number[]): number {
  if (values.length !== weights.length) throw new Error('Values and weights must match');
  let result = 0;
  for (let i = 0; i < values.length; i++) {
    result += values[i] * weights[i];
  }
  return result;
}

/** RFD ratio calculation */
export function calculateRFD(possibilityBefore: number, possibilityAfter: number): number {
  if (possibilityBefore <= 0) return 0;
  return (possibilityAfter - possibilityBefore) / possibilityBefore;
}

/** CSIA risk level from composite score (0-100) */
export function csiaRiskLevel(score: number): 'L1' | 'L2' | 'L3' | 'L4' {
  if (score <= 25) return 'L1';
  if (score <= 50) return 'L2';
  if (score <= 75) return 'L3';
  return 'L4';
}

/** MBCL level from matrix (spreadLevel 0-2, impactLevel 0-3) */
export function mbclLevel(spreadLevel: number, impactLevel: number): number {
  const s = Math.min(Math.max(Math.round(spreadLevel), 0), 2);
  const i = Math.min(Math.max(Math.round(impactLevel), 0), 3);
  return MBCL_MATRIX[i][s];
}

/** Calculate UCS aggregate from five dimension scores */
export function calculateUCS(phi: number, t: number, r: number, v: number, s: number): number {
  return weightedGeometricMean([phi, t, r, v, s], [0.25, 0.20, 0.20, 0.20, 0.15]);
}

/** Calculate CDI aggregate from five dimension scores */
export function calculateCDI(e: number, i: number, m: number, s: number, g: number): number {
  return weightedGeometricMean([e, i, m, s, g], [0.20, 0.20, 0.20, 0.20, 0.20]);
}

/** Calculate CRV aggregate from three dimension scores */
export function calculateCRV(vObs: number, vEnf: number, vRev: number): number {
  return weightedArithmeticMean([vObs, vEnf, vRev], [0.35, 0.35, 0.30]);
}

/** Calculate CSIA composite score (0-100) from six dimensions
 *  Note: d4 (reversibility) is inverted — pass raw reversibility score
 */
export function calculateCSIA(
  d1: number, d2: number, d3: number, d4_raw_reversibility: number, d5: number, d6: number
): number {
  const d4 = 1 - d4_raw_reversibility; // invert: high reversibility = low risk
  return weightedArithmeticMean(
    [d1, d2, d3, d4, d5, d6],
    [0.15, 0.15, 0.20, 0.20, 0.15, 0.15]
  ) * 100;
}

