import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import en from './en';
import zh from './zh';

const savedLang = (typeof window !== 'undefined' && localStorage.getItem('ics-compass-lang')) || 'en';

i18n.use(initReactI18next).init({
  resources: {
    en: { translation: en },
    zh: { translation: zh },
  },
  lng: savedLang,
  fallbackLng: 'en',
  interpolation: {
    escapeValue: false,
  },
});

// Persist language choice
i18n.on('languageChanged', (lng) => {
  if (typeof window !== 'undefined') {
    localStorage.setItem('ics-compass-lang', lng);
    document.documentElement.lang = lng === 'zh' ? 'zh-CN' : 'en';
  }
});

export default i18n;
